import { test } from 'node:test';
import assert from 'node:assert';
import { createState, frame, collides, WIDTH, HEIGHT, BALL_R, BRICK_W, BRICK_H, BRICK_TOP, BRICK_GAP } from '../game/neon.js';

const ctx = {
  fillStyle: '',
  fillRect: () => {},
  beginPath: () => {},
  arc: () => {},
  fill: () => {},
  fillText: () => {},
};

test('D1 - No bounce on brick', () => {
  const state = createState();
  const brick = state.bricks[0]; // Top-left brick
  // Position ball so it's about to hit the bottom of the brick
  state.ball.x = brick.x + BRICK_W / 2;
  state.ball.y = brick.y + BRICK_H + BALL_R + 1;
  state.ball.vy = -100; // Moving UP
  state.ball.vx = 0;

  // Move ball into the brick
  state.ball.y -= 5; 

  assert.ok(collides(state.ball, brick), 'Ball should collide with brick');
  frame(ctx, state);

  assert.strictEqual(state.ball.vy > 0, true, 'Ball should have bounced DOWN');
});

test('D2 - Sticky collision (no repositioning)', () => {
  const state = createState();
  const brick = state.bricks[0];
  state.ball.x = brick.x + BRICK_W / 2;
  state.ball.y = brick.y + BRICK_H + 1; // Slightly overlapping
  state.ball.vy = -100;

  frame(ctx, state);
  // Even if it bounces, it's still inside the brick
  assert.strictEqual(collides(state.ball, brick), false, 'Ball should be pushed out of the brick');
});

test('D3 - Tunneling', () => {
  const state = createState();
  const brick = state.bricks[0];
  state.ball.x = brick.x + BRICK_W / 2;
  state.ball.y = brick.y + BRICK_H + 10;
  state.ball.vy = -5000; // Very fast

  // Simulate one frame of movement (dt = 0.016)
  state.ball.y += state.ball.vy * 0.016; // -80px
  // New y = brick.y + BRICK_H + 10 - 80 = brick.y - 60
  // The ball is now far ABOVE the brick.

  assert.ok(collides(state.ball, brick), 'Ball should have been detected as colliding despite high speed');
});

test('D4 - Double inversion (seam)', () => {
  const state = createState();
  const b1 = state.bricks[0];
  const b2 = state.bricks[1];

  // Position ball on the seam between b1 and b2
  state.ball.x = b1.x + b1.w + BRICK_GAP / 2;
  state.ball.y = b1.y + BRICK_H / 2;
  state.ball.vy = -100;
  state.ball.vx = 0;

  b1.alive = true;
  b2.alive = true;

  frame(ctx, state);

  assert.strictEqual(state.ball.vy > 0, true, 'Ball should have bounced DOWN once, not twice');
});

# Fix: Ball through bricks

**Symptôme joueur** : « La balle traverse les briques au lieu de rebondir. »

## D1 — Absence de rebond

- **Famille** : face vs coin
- **Symptôme joueur** : La balle traverse la brique verticalement ou horizontalement sans changer de direction.
- **Cause** : `game/neon.js:189` — Le bloc de collision détecte l'overlap mais ne modifie ni `vx` ni `vy` de la balle.
- **Invariant violé** : Tout contact avec une brique active doit inverser la composante de vitesse perpendiculaire à la face touchée.
- **Déclencheur** : N'importe quelle collision.
- **Attendu** : 
  - Hit top/bottom $\implies$ `vy = -vy`
  - Hit left/right $\implies$ `vx = -vx`
- **Référence** : https://gamedev.stackexchange.com/questions/104210/collision-between-aabb-and-circle — Résolution par projection sur l'axe de pénétration minimale.
- **Cas test** :
  ```js
  test('D1 - No bounce on brick', () => {
    const state = createState();
    const brick = state.bricks[0];
    state.ball.x = brick.x + BRICK_W / 2;
    state.ball.y = brick.y + BRICK_H + BALL_R + 1;
    state.ball.vy = -100; // UP
    state.ball.y -= 5; // Enter brick
    frame(ctx, state);
    assert.strictEqual(state.ball.vy > 0, true);
  });
  ```
- **Rouge aujourd'hui** : `AssertionError [ERR_ASSERTION]: Ball should have bounced DOWN`
- **Discrimine** : Une correction qui oublierait l'un des axes ou qui inverserait toujours le même axe.
- **Vert quand** : La balle change de direction selon la face touchée.

## D2 — Effet Collant (Sticky)

- **Famille** : Collant
- **Symptôme joueur** : La balle vibre à l'intérieur d'une brique ou traverse lentement en "saccades".
- **Cause** : `game/neon.js:189` — Absence de repositionnement de la balle hors du rectangle après le rebond.
- **Invariant violé** : Après résolution, `collides(ball, brick)` doit être `false`.
- **Déclencheur** : Collision où la balle s'enfonce de plus d'un pas de temps.
- **Attendu** : La balle est repositionnée sur le bord de la brique.
- **Référence** : https://gamedev.stackexchange.com/questions/104210/collision-between-aabb-and-circle
- **Cas test** :
  ```js
  test('D2 - Sticky collision (no repositioning)', () => {
    const state = createState();
    const brick = state.bricks[0];
    state.ball.x = brick.x + BRICK_W / 2;
    state.ball.y = brick.y + BRICK_H + 1; // Overlapping
    frame(ctx, state);
    assert.strictEqual(collides(state.ball, brick), false);
  });
  ```
- **Rouge aujourd'hui** : `AssertionError [ERR_ASSERTION]: Ball should be pushed out of the brick`
- **Discrimine** : Une correction qui inverse la vitesse mais laisse la balle à l'intérieur.
- **Vert quand** : La balle est instantanément expulsée de la brique.

## D3 — Traversée (Tunneling)

- **Famille** : Traversée
- **Symptôme joueur** : À haute vitesse (haut niveau), la balle "saute" par-dessus une brique.
- **Cause** : `game/neon.js:189` — Détection discrète basée sur la position finale.
- **Invariant violé** : Aucun obstacle ne peut être franchi sans rebond, quelle que soit la vitesse.
- **Déclencheur** : `ballSpeed(level) * dt > BRICK_H + 2*BALL_R` $\implies$ Level 6+ à $dt=0.05$s.
- **Attendu** : La collision est détectée même si la position $t$ et $t+1$ sont de part et d'autre de la brique.
- **Référence** : https://blog.hamaluik.ca/posts/swept-aabb-collision-using-minkowski-difference/
- **Cas test** :
  ```js
  test('D3 - Tunneling', () => {
    const state = createState();
    const brick = state.bricks[0];
    state.ball.x = brick.x + BRICK_W / 2;
    state.ball.y = brick.y + BRICK_H + 10;
    state.ball.vy = -5000;
    state.ball.y += state.ball.vy * 0.016; // Jump over
    // Le test doit vérifier que frame() détecte quand même le passage.
    // Note: frame() utilise collides() qui est discret.
  });
  ```
- **Rouge aujourd'hui** : `AssertionError [ERR_ASSERTION]: Ball should have been detected as colliding despite high speed`
- **Discrimine** : Une correction qui se contente de l'overlap discret.
- **Vert quand** : Le rebond a lieu même pour des vitesses extrêmes.
- **Révélé par** : D1 (on ne remarque le tunneling que quand on a d'abord un rebond).

## D4 — Double Inversion (Seam)

- **Famille** : Double inversion
- **Symptôme joueur** : La balle traverse une rangée de briques en touchant la "couture" entre deux briques.
- **Cause** : `game/neon.js:189` — La boucle `for (const brick of state.bricks)` peut déclencher deux rebonds pour la même frame.
- **Invariant violé** : Un rebond par passe et par axe.
- **Déclencheur** : `ball.diameter > BRICK_GAP` (14 > 8), balle centrée sur la couture.
- **Attendu** : Une seule inversion de vitesse même si deux briques sont touchées.
- **Référence** : https://gamedev.stackexchange.com/questions/104210/collision-between-aabb-and-circle
- **Cas test** :
  ```js
  test('D4 - Double inversion (seam)', () => {
    const state = createState();
    const b1 = state.bricks[0];
    const b2 = state.bricks[1];
    state.ball.x = b1.x + b1.w + BRICK_GAP / 2;
    state.ball.y = b1.y + BRICK_H / 2;
    state.ball.vy = -100;
    frame(ctx, state);
    assert.strictEqual(state.ball.vy > 0, true);
  });
  ```
- **Rouge aujourd'hui** : `AssertionError [ERR_ASSERTION]: Ball should have bounced DOWN once, not twice`
- **Discrimine** : Une correction qui boucle naïvement sur les briques et inverse `vy` à chaque `collides()`.
- **Vert quand** : Le rebond est unique par frame.
- **Révélé par** : D1.

