edits.newText:
// True if the ball (circle approximated by its box) overlaps the brick.
// Simple AABB test: it only says WHETHER the ball and the brick overlap, not
// WHICH face was hit. The missing bounce in frame() is what lets the ball plow
// straight through bricks (see #1).
export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

function resolveBrickCollision(ball, brick) {
  // 1. Tunneling check: did we jump over the brick?
  // We check if the movement segment from prev to current intersects the brick.
  // Since we only care about Y-tunneling (X is too wide to jump), we check Y.
  const jumpedOver = (ball.prevY - ball.r <= brick.y && ball.y + ball.r >= brick.y + brick.h) ||
                    (ball.prevY + ball.r >= brick.y + brick.h && ball.y - ball.r <= brick.y);
  const xOverlap = ball.x + ball.r > brick.x && ball.x - ball.r < brick.x + brick.w;

  if (jumpedOver && xOverlap) {
    ball.vy = -ball.vy;
    // Reposition to the edge we came from
    ball.y = ball.prevY < ball.y ? brick.y + brick.h + ball.r : brick.y - ball.r;
    return true;
  }

  if (!collides(ball, brick)) return false;

  // 2. Discrete resolution
  // Find penetration on each axis
  const overlapX = Math.min(ball.x + ball.r - brick.x, brick.x + brick.w - (ball.x - ball.r));
  const overlapY = Math.min(ball.y + ball.r - brick.y, brick.y + brick.h - (ball.y - ball.r));

  if (overlapX < overlapY) {
    // X-axis hit
    ball.vx = -ball.vx;
    ball.x = ball.x < brick.x + brick.w / 2 ? brick.x - ball.r : brick.x + brick.w + ball.r;
  } else if (overlapY < overlapX) {
    // Y-axis hit
    ball.vy = -ball.vy;
    ball.y = ball.y < brick.y + brick.h / 2 ? brick.y - ball.r : brick.y + brick.h + ball.r;
  } else {
    // Corner hit
    ball.vx = -ball.vx;
    ball.vy = -ball.vy;
    // Push out along the axis of movement
    if (ball.vx > 0) ball.x = brick.x - ball.r; else ball.x = brick.x + brick.w + ball.r;
    if (ball.vy > 0) ball.y = brick.y - ball.r; else ball.y = brick.y + brick.h + ball.r;
  }
  return true;
}

